# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_browser() {
    _choice_command
}

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_encoding() {
    command -v iconv >/dev/null || return 0
    iconv -l 2>/dev/null | sed 's#//$##'
}

_choice_locale() {
    command -v locale >/dev/null || return 0
    locale -a 2>/dev/null
}

_choice_page() {
    if [[ -n "$argc_local_file" ]]; then
        _argc_util_comp_path
        return
    fi
    local dirs=$argc_manpath dir
    if [[ -z "$dirs" ]]; then
        command -v manpath >/dev/null || return 0
        dirs=$(manpath -q 2>/dev/null)
    fi
    local IFS=:
    for dir in $dirs; do
        [[ -d "$dir" ]] || continue
        find "$dir" -maxdepth 2 \( -type f -o -type l \) -path '*/man*/*' 2>/dev/null
    done | gawk -F/ '{
        name = $NF
        sub(/\.(gz|bz2|xz|lzma|zst|Z)$/, "", name)
        sub(/\.[0-9][A-Za-z0-9]*$/, "", name)
        if (name != "") print name
    }'
}

_choice_pager() {
    _choice_command
}

_choice_preprocessor() {
    printf '%s\t%s\n' \
        e 'eqn preprocessor' \
        n 'neqn preprocessor' \
        p 'pic preprocessor' \
        t 'tbl preprocessor' \
        g 'grap preprocessor' \
        r 'refer preprocessor' \
        v 'vgrind preprocessor'
}

_choice_section() {
    printf '%s\t%s\n' \
        1 'Executable programs or shell commands' \
        2 'System calls' \
        3 'Library calls' \
        4 'Special files' \
        5 'File formats and conventions' \
        6 'Games' \
        7 'Miscellaneous' \
        8 'System administration commands' \
        9 'Kernel routines' \
        n 'Tcl/Tk commands' \
        l 'Local documentation'
}

_choice_section_or_page() {
    if [[ -n "$argc_local_file" ]]; then
        _argc_util_comp_path
        return
    fi
    if [[ -n "$argc_apropos" || -n "$argc_whatis" || -n "$argc_global_apropos" ]]; then
        _choice_page
        return
    fi
    _choice_section
    _choice_page
}

_choice_troff_device() {
    local dir devices=""
    for dir in /usr/share/groff/*/font/dev* /usr/local/share/groff/*/font/dev*; do
        [[ -d "$dir" ]] || continue
        devices="$devices ${dir##*/dev}"
    done
    [[ -n "$devices" ]] || return 0
    printf '%s\n' $devices
}
